use crate::runtime::Cpu;

pub const MOVE_MON_FROM_PARTY_F: u8 = 0;

pub const MOVE_MON_TO_PARTY_F: u8 = 1;

pub const CURRENT_TABLE_WIDTH: u8 = 3;

pub const W: u8 = 14;

pub const X: u8 = 42;

pub const Y: i32 = 0;

